CREATE TABLE "editors" (
  "editor_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "editor_login" varchar,
  "editor_name_last" varchar,
  "editor_name_first" varchar,
  "permissions" integer
);

CREATE TABLE "games" (
  "gidb_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mobygames_id" integer UNIQUE,
  "igdb_id" integer UNIQUE,
  "steam_id" integer UNIQUE,
  "gog_id" integer UNIQUE,
  "itch_id" varchar UNIQUE,
  "wikidata_id" varchar UNIQUE,
  "game_title" text,
  "game_parent_id" integer,
  "game_year" smallint,
  "game_url" varchar,
  "gidb_status" varchar,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp,
  "modified_at" timestamp
);

CREATE TABLE "collections" (
  "collection_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "collection_name" varchar UNIQUE,
  "collection_description" text,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp,
  "modified_at" timestamp
);

CREATE TABLE "games_collections_map" (
  "gidb_id" integer,
  "collection_id" integer,
  PRIMARY KEY ("gidb_id", "collection_id")
);

CREATE TABLE "categories" (
  "category_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_value" varchar,
  "category_source" varchar
);

CREATE TABLE "tags" (
  "tag_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tag_value" varchar,
  "category_id" integer
);

CREATE TABLE "tags_games_map" (
  "tag_id" integer,
  "gidb_id" integer,
  PRIMARY KEY ("tag_id", "gidb_id")
);

CREATE TABLE "originator_roles" (
  "originator_role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "originator_role" varchar UNIQUE
);

CREATE TABLE "originators" (
  "originator_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "originator_mobygames_id" integer,
  "originator_igdb_id" integer,
  "originator_name" varchar,
  "originator_description" text
);

CREATE TABLE "originators_games_map" (
  "originator_id" integer,
  "gidb_id" integer,
  "originator_role" integer,
  PRIMARY KEY ("originator_id", "gidb_id")
);

CREATE TABLE "originators_locations_map" (
  "originator_id" integer,
  "location_id" integer,
  PRIMARY KEY ("originator_id", "location_id")
);

CREATE TABLE "notes" (
  "note_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "note" text,
  "gidb_id" integer,
  "source_id" integer,
  "reference_id" integer,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp,
  "modified_at" timestamp
);

CREATE TABLE "countries" (
  "country_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "geonames_id" integer UNIQUE,
  "country_code" varchar,
  "country_name" varchar
);

CREATE TABLE "locations" (
  "location_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "geonames_id" integer UNIQUE,
  "latitude" decimal,
  "longitude" decimal,
  "location_name" varchar,
  "country_id" integer
);

CREATE TABLE "attachments" (
  "attachment_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "gidb_id" integer,
  "sign_id" integer,
  "source_id" integer,
  "attachment_path" varchar,
  "attachment_filename" varchar,
  "attachment_mime" varchar,
  "attachment_type" varchar,
  "attachment_source" varchar,
  "attachment_license" varchar,
  "attachment_publishable" boolean,
  "attachment_description" text,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp,
  "modified_at" timestamp
);

CREATE TABLE "signs" (
  "sign_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "gidb_id" integer,
  "sign_name" varchar,
  "description" text
);

CREATE TABLE "sources" (
  "source_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sign_id" integer,
  "location_id" integer,
  "technology" varchar
);

CREATE TABLE "references" (
  "reference_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sign_id" integer,
  "location_id" integer,
  "is_direct" bool,
  "is_fictional" bool,
  "period_id" integer
);

CREATE TABLE "periods" (
  "period_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "period_name" varchar UNIQUE,
  "year_from" integer,
  "year_to" interger,
  "wikidata_id" varchar
);

